MmPayrollBulk.ListOfMmPayroll:
{{- $d := .Doc}}
{{- range .Related.slips}}
{{- $tin := digits .slip_nik}}
{{- if eq (len (digits .slip_npwp)) 16}}{{$tin = digits .slip_npwp}}{{else if eq (len (digits .slip_npwp)) 15}}{{$tin = print "0" (digits .slip_npwp)}}{{end}}
{{- $m := 100}}{{if not .has_tax_id}}{{$m = 120}}{{end}}

			{{dec $d.month 0}}
			{{$d.year}}
			Resident

			{{$tin}}
			{{if eq (slice .ptkp_status 0 1) "t"}}TK/{{slice .ptkp_status 2}}{{else}}K/{{slice .ptkp_status 1}}{{end}}
			{{or .slip_role_title "Staff"}}
			N/A
			21-100-01
			{{dec .gross_taxable 0}}
			{{dec (div (mul .ter_bp $m) 10000) 4}}
			{{$d.seller_nitku}}
			{{isodate $d.withholding_date}}

{{- end}}
